import { Plus_Jakarta_Sans } from "next/font/google";
import localFont from "next/font/local";

// Display + Japanese fonts are glyph subsets of the Google Fonts originals (OFL),
// generated by `npm run fonts`, so they cost ~40 KB instead of hundreds.
export const dela = localFont({
  src: "../assets/fonts/dela-gothic-one-latin.woff2",
  weight: "400",
  display: "swap",
  variable: "--font-dela",
});
export const zen = localFont({
  src: "../assets/fonts/zen-kaku-gothic-new-700-subset.woff2",
  weight: "700",
  display: "swap",
  variable: "--font-zen",
});
export const jakarta = Plus_Jakarta_Sans({
  subsets: ["latin"],
  display: "swap",
  variable: "--font-jakarta",
});
